export function traceBeam(puzzle, orientations) {
  const byKey = new Map();
  puzzle.mirrors.forEach((m,i)=>byKey.set(m.y*puzzle.w+m.x, i));
  const crystalAt = new Map(puzzle.crystals.map((c,i)=>[c.y*puzzle.w+c.x,i]));
  const wallSet = new Set(puzzle.walls.map(w=>w.y*puzzle.w+w.x));
  let x=puzzle.emitter.x, y=puzzle.emitter.y, dir=puzzle.emitter.dir;
  const points=[{x,y}];
  const lit=[]; const seen=new Set(); let loop=false;
  for (let step=0; step<400; step++) {
    const state = `${x},${y},${dir}`;
    if (seen.has(state)) { loop=true; break; }
    seen.add(state);
    const [dx,dy]=DIRS[dir]; x+=dx; y+=dy;
    points.push({x,y});
    if (x<0||y<0||x>=puzzle.w||y>=puzzle.h) break;
    if (wallSet.has(y*puzzle.w+x)) break;
    const mi = byKey.get(y*puzzle.w+x);
    if (mi !== undefined) dir = REFLECT[orientations[mi]][dir];
    const ci = crystalAt.get(y*puzzle.w+x);
    if (ci !== undefined && !lit.includes(ci)) lit.push(ci);
  }
  return { points, lit, loop };
}
