:root {
  color-scheme: dark;
  --bg: #050711;
  --bg-2: #070c1d;
  --panel: rgba(12, 18, 40, 0.68);
  --panel-strong: rgba(15, 22, 47, 0.92);
  --stroke: rgba(132, 166, 255, 0.14);
  --stroke-strong: rgba(132, 166, 255, 0.26);
  --text: #eef3ff;
