  gap: 16px;
  height: 74px;
  padding: env(safe-area-inset-top, 0px) clamp(16px, 3.2vw, 46px) 0;
  background: linear-gradient(180deg, rgba(5, 7, 17, 0.94) 0%, rgba(5, 7, 17, 0.72) 60%, rgba(5, 7, 17, 0) 100%);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  justify-self: start;
  color: var(--cyan);
  min-width: 0;
}

.brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: linear-gradient(145deg, rgba(94, 243, 255, 0.09), rgba(154, 123, 255, 0.06));
  border: 1px solid rgba(94, 243, 255, 0.16);
  box-shadow: inset 0 0 22px rgba(94, 243, 255, 0.06);
  flex: 0 0 auto;
}

.brand-mark svg {
  width: 34px;
  height: 34px;
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand-text strong {
  color: var(--text);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.brand-text small {
  color: var(--muted);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-top: 3px;
}

.week-pill {
  justify-self: center;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 14px;
  border-radius: 99px;
  border: 1px solid var(--stroke);
  background: rgba(11, 17, 36, 0.62);
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  white-space: nowrap;
  backdrop-filter: blur(10px);
}

.week-pill .mono {
  color: var(--text);
  font-size: 10px;
  letter-spacing: 0.02em;
}

.week-sep {
  color: rgba(138, 151, 189, 0.35);
}

.pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 0 0 rgba(94, 243, 255, 0.55);
  animation: pulseDot 2.4s infinite;
  flex: 0 0 auto;
}

@keyframes pulseDot {
  0% { box-shadow: 0 0 0 0 rgba(94, 243, 255, 0.45); }
  65% { box-shadow: 0 0 0 7px rgba(94, 243, 255, 0); }
  100% { box-shadow: 0 0 0 0 rgba(94, 243, 255, 0); }
}

.top-actions {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ----------------------------------- Buttons -------------------------------- */

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 15px;
  border-radius: 12px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: transform 0.18s var(--ease), background 0.18s, border-color 0.18s, color 0.18s, box-shadow 0.18s;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0) scale(0.985);
}

.btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
  transform: none;
}

.btn svg {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
}

.btn-primary {
  background: linear-gradient(120deg, #8dfaff 0%, #58f3ff 32%, #9d8bff 72%, #ff8fe8 110%);
  color: #04101a;
  border: none;
  box-shadow: 0 8px 30px rgba(64, 216, 255, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.btn-primary:hover {
  box-shadow: 0 12px 38px rgba(64, 216, 255, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.65);
}

.btn-large {
  height: 54px;
  padding: 0 24px;
  border-radius: 15px;
  font-size: 14px;
  letter-spacing: 0.01em;
}

.btn-large svg {
  width: 18px;
  height: 18px;
}

.btn-quiet {
  color: var(--muted);
  height: 36px;
  padding: 0 11px;
}

.btn-quiet:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
}

.btn-league {
  height: 38px;
  border-color: rgba(94, 243, 255, 0.2);
  background: rgba(94, 243, 255, 0.06);
  color: #c9faff;
}

.btn-league:hover {
  background: rgba(94, 243, 255, 0.1);
  border-color: rgba(94, 243, 255, 0.35);
}

.btn-outline {
  border-color: var(--stroke-strong);
  background: rgba(255, 255, 255, 0.025);
  color: var(--text);
}

.btn-outline:hover {
  border-color: rgba(94, 243, 255, 0.4);
  background: rgba(94, 243, 255, 0.07);
}

.btn-soft {
  height: 38px;
  padding: 0 12px;
  border-color: var(--stroke);
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-size: 11px;
  border-radius: 11px;
}

.btn-soft:hover {
  color: var(--text);
  border-color: rgba(94, 243, 255, 0.3);
  background: rgba(94, 243, 255, 0.06);
}

.btn-soft .penalty {
  color: var(--gold);
  font-family: var(--mono);
  font-size: 9px;
  opacity: 0.9;
}

.btn.full {
  width: 100%;
}

.btn-ghost {
  color: var(--muted);
  border-color: transparent;
  background: transparent;
}

.btn-ghost:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
}

.icon-btn {
  width: 38px;
  height: 38px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--stroke);
  border-radius: 11px;
  background: rgba(11, 17, 36, 0.55);
  color: var(--muted);
  cursor: pointer;
  transition: color 0.18s, background 0.18s, border-color 0.18s, transform 0.18s;
}

.icon-btn:hover {
  color: var(--text);
  border-color: var(--stroke-strong);
  background: rgba(255, 255, 255, 0.045);
}

.icon-btn:active {
  transform: scale(0.96);
}

.icon-btn svg {
  width: 17px;
  height: 17px;
}

.icon-btn.small {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  font-family: var(--mono);
  font-size: 12px;
}

.icon-sound-off {
  display: none;
}

body.muted .icon-sound-on {
  display: none;
}

body.muted .icon-sound-off {
  display: block;
}

.link-btn {
  display: inline;
  padding: 0;
  border: 0;
  background: none;
  color: var(--cyan);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: color 0.18s, opacity 0.18s;
}

.link-btn:hover {
  color: #b7fbff;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 11px;
  border-radius: 99px;
  border: 1px solid var(--stroke);
  background: rgba(10, 16, 34, 0.56);
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  white-space: nowrap;
  backdrop-filter: blur(8px);
}

.chip-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex: 0 0 auto;
}

.chip-dot.cyan { background: var(--cyan); box-shadow: 0 0 8px rgba(94, 243, 255, 0.7); }
.chip-dot.magenta { background: var(--magenta); box-shadow: 0 0 8px rgba(255, 95, 220, 0.7); }
.chip-dot.gold { background: var(--gold); box-shadow: 0 0 8px rgba(255, 207, 112, 0.7); }

/* ---------------------------------- Layout --------------------------------- */

.layout {
  width: 100%;
  max-width: 1510px;
  margin: 0 auto;
  padding: 22px clamp(16px, 3.2vw, 46px) 46px;
  display: grid;
  grid-template-columns: minmax(214px, 252px) minmax(0, 1fr) minmax(272px, 326px);
  gap: clamp(16px, 2vw, 26px);
  align-items: start;
}

.panel {
  position: relative;
  border: 1px solid var(--stroke);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(17, 24, 50, 0.76), rgba(8, 12, 28, 0.74));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035), 0 20px 60px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.side-panel {
  position: sticky;
  top: 94px;
  padding: 18px;
}

.panel-eyebrow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--dim);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.panel-eyebrow span {
  color: var(--muted);
  letter-spacing: 0.08em;
  font-family: var(--mono);
  font-size: 9px;
}

/* ------------------------------- Stats panel ------------------------------- */

.score-block {
  position: relative;
  padding: 2px 0 18px;
  border-bottom: 1px solid rgba(132, 166, 255, 0.09);
}

.score-label {
  display: block;
  color: var(--dim);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.2em;
  margin-bottom: 7px;
}

.score-value {
  display: block;
  font-size: clamp(30px, 3vw, 40px);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.04em;
  color: #fff;
  text-shadow: 0 0 32px rgba(94, 243, 255, 0.18);
}

.score-value.bump {
  animation: scoreBump 0.45s var(--ease);
}

@keyframes scoreBump {
  0% { transform: scale(1); color: #fff; }
  35% { transform: scale(1.06); color: var(--cyan); }
  100% { transform: scale(1); color: #fff; }
}

.score-delta {
  position: absolute;
  right: 0;
  bottom: 22px;
  color: var(--green);
  font-size: 11px;
  font-weight: 600;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.3s, transform 0.3s;
}

.score-delta.show {
  opacity: 1;
  transform: translateY(0);
}

.level-progress {
  padding: 16px 0 14px;
  border-bottom: 1px solid rgba(132, 166, 255, 0.09);
}

.level-progress-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--dim);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.16em;
  margin-bottom: 10px;
}

.level-progress-head b {
  color: var(--text);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
}

.level-dots {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 5px;
}

.level-dot {
  height: 5px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.075);
  overflow: hidden;
  position: relative;
  transition: background 0.3s;
}

.level-dot.done {
  background: linear-gradient(90deg, var(--cyan), var(--violet));
  box-shadow: 0 0 10px rgba(94, 243, 255, 0.32);
}

.level-dot.current {
  background: rgba(94, 243, 255, 0.32);
}

.level-dot.current::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--cyan);
  animation: dotPulse 1.8s ease-in-out infinite;
}

@keyframes dotPulse {
  0%, 100% { opacity: 0.25; }
  50% { opacity: 0.85; }
}

.stat-list {
  padding: 13px 0 5px;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.stat-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 0;
  color: var(--muted);
  font-size: 11px;
}

.stat-row strong {
  color: var(--text);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.01em;
}

.stat-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-top: 12px;
}

.panel-note {
  margin-top: 14px;
  padding-top: 13px;
  border-top: 1px solid rgba(132, 166, 255, 0.08);
  color: var(--dim);
  font-size: 9px;
  line-height: 1.7;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  margin: 0 1px;
  border: 1px solid rgba(132, 166, 255, 0.18);
  border-bottom-color: rgba(132, 166, 255, 0.28);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.035);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  vertical-align: 1px;
}

/* ----------------------------------- Stage --------------------------------- */

.stage {
  width: 100%;
  max-width: 748px;
  margin: 0 auto;
  min-width: 0;
}

.stage-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding: 0 4px;
  margin-bottom: 13px;
}

.stage-title {
  min-width: 0;
}

.eyebrow {
  color: var(--cyan);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  margin-bottom: 4px;
  opacity: 0.85;
}

.stage-head h1 {
  margin: 0;
  font-size: clamp(21px, 2vw, 27px);
  font-weight: 600;
  letter-spacing: -0.025em;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stage-chips {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.mobile-stats {
  display: none;
}

.board-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 664px;
  margin: 0 auto;
  border-radius: 30px;
  isolation: isolate;
}

.board-frame::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: 31px;
  padding: 1px;
  background: linear-gradient(145deg, rgba(94, 243, 255, 0.32), rgba(132, 166, 255, 0.08) 35%, rgba(255, 95, 220, 0.16));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  z-index: 2;
}

.board-frame::after {
  content: '';
  position: absolute;
  inset: 4%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(94, 243, 255, 0.08), transparent 66%);
  filter: blur(30px);
  z-index: -1;
  pointer-events: none;
}

#board {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 30px;
  touch-action: none;
  cursor: crosshair;
  background: #050a18;
  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.55),
    0 0 0 1px rgba(132, 166, 255, 0.1),
    inset 0 0 60px rgba(8, 17, 46, 0.8);
}

.frame-corner {
  position: absolute;
  width: 20px;
  height: 20px;
  z-index: 3;
  pointer-events: none;
  opacity: 0.62;
}

.frame-corner::before,
.frame-corner::after {
  content: '';
  position: absolute;
  background: var(--cyan);
  box-shadow: 0 0 8px rgba(94, 243, 255, 0.55);
  border-radius: 2px;
}

.frame-corner::before { width: 100%; height: 1px; }
.frame-corner::after { width: 1px; height: 100%; }
.frame-corner.tl { top: 14px; left: 14px; }
.frame-corner.tr { top: 14px; right: 14px; transform: rotate(90deg); }
.frame-corner.br { bottom: 14px; right: 14px; transform: rotate(180deg); }
.frame-corner.bl { bottom: 14px; left: 14px; transform: rotate(270deg); }

.board-toast {
  position: absolute;
  top: 18px;
  left: 50%;
  z-index: 5;
  transform: translate(-50%, -8px);
  padding: 8px 14px;
  border-radius: 99px;
  border: 1px solid rgba(94, 243, 255, 0.24);
  background: rgba(6, 12, 27, 0.86);
  color: #d8fbff;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.03em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.board-toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.board-toast.warn {
  border-color: rgba(255, 207, 112, 0.3);
  color: var(--gold);
}

.stage-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 4px 0;
}

.foot-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.03em;
  min-width: 0;
}

.status-orb {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 0 4px rgba(94, 243, 255, 0.08);
  flex: 0 0 auto;
  transition: background 0.3s, box-shadow 0.3s;
}

.status-orb.done {
  background: var(--gold);
  box-shadow: 0 0 0 4px rgba(255, 207, 112, 0.1);
}

.status-orb.warn {
  background: var(--gold);
  box-shadow: 0 0 0 4px rgba(255, 207, 112, 0.1);
}

.legend {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--dim);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend i {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 2px;
}

.legend-mirror {
  border: 1px solid var(--cyan);
  transform: rotate(45deg) scale(0.85);
  background: rgba(94, 243, 255, 0.14);
}

.legend-crystal {
  background: linear-gradient(135deg, #ff9be9, #9a5cff);
  transform: rotate(45deg) scale(0.8);
}

.legend-emitter {
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 6px rgba(94, 243, 255, 0.7);
}

/* ------------------------------- League panel ------------------------------ */

.league-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}

.league-head .panel-eyebrow {
  margin-bottom: 3px;
}

.league-head h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.mini-board {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 10px -5px 12px;
}

.mini-row {
  display: grid;
  grid-template-columns: 20px 27px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 6px 5px;
  border-radius: 9px;
  transition: background 0.2s;
}

.mini-row.self {
  background: rgba(94, 243, 255, 0.06);
  box-shadow: inset 0 0 0 1px rgba(94, 243, 255, 0.12);
}

.mini-rank {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 9px;
  text-align: right;
}

.mini-avatar {
  width: 27px;
  height: 27px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  color: #06101a;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: linear-gradient(135deg, var(--a, #58f3ff), var(--b, #9a7bff));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.mini-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-size: 11px;
  font-weight: 500;
}

.mini-row.self .mini-name {
  color: var(--text);
}

.mini-score {
  color: var(--text);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
}

.mini-row.top-1 .mini-rank { color: var(--gold); }
.mini-row.top-2 .mini-rank { color: #cfd8ea; }
.mini-row.top-3 .mini-rank { color: #e3a177; }

.rank-card {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 2px 12px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(94, 243, 255, 0.13);
  background:
    linear-gradient(120deg, rgba(94, 243, 255, 0.07), rgba(154, 123, 255, 0.05)),
    rgba(8, 13, 29, 0.65);
}

.rank-card-label {
  color: var(--dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

.rank-card strong {
  grid-row: span 2;
  font-size: 28px;
  font-weight: 500;
  line-height: 1;
  color: var(--cyan);
  text-shadow: 0 0 20px rgba(94, 243, 255, 0.3);
}

.rank-card > span:last-child {
  color: var(--muted);
  font-size: 10px;
}

.league-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 12px 0;
  color: var(--dim);
  font-size: 9px;
}

.mode-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: 99px;
  border: 1px solid rgba(154, 123, 255, 0.2);
  background: rgba(154, 123, 255, 0.07);
  color: #cbbdff;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.mode-pill.remote {
  border-color: rgba(109, 255, 176, 0.24);
  background: rgba(109, 255, 176, 0.07);
  color: #b5ffd8;
}

/* -------------------------------- Start screen ----------------------------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 50;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.start-screen {
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(ellipse 70% 55% at 12% 18%, rgba(33, 139, 196, 0.12), transparent 60%),
    radial-gradient(ellipse 55% 50% at 92% 68%, rgba(148, 66, 196, 0.12), transparent 62%),
    radial-gradient(ellipse 50% 40% at 50% 110%, rgba(94, 243, 255, 0.05), transparent 70%),
    #050711;
  opacity: 1;
  visibility: visible;
  transition: opacity 0.55s var(--ease), visibility 0.55s;
}

.start-screen.is-leaving {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.start-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.55;
  background-image:
    linear-gradient(rgba(122, 153, 255, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(122, 153, 255, 0.04) 1px, transparent 1px);
  background-size: 52px 52px;
  mask-image: radial-gradient(ellipse 65% 65% at 50% 45%, #000 10%, transparent 76%);
  -webkit-mask-image: radial-gradient(ellipse 65% 65% at 50% 45%, #000 10%, transparent 76%);
}

.start-content {
  position: relative;
  z-index: 1;
  width: min(1300px, 100%);
  margin: auto;
  padding: clamp(36px, 6vh, 80px) clamp(22px, 5vw, 74px) clamp(28px, 5vh, 56px);
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(360px, 0.98fr);
  align-items: center;
  gap: clamp(28px, 5vw, 82px);
  flex: 1 0 auto;
}

.start-hero {
  position: relative;
  z-index: 2;
  max-width: 610px;
}

.season-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 28px;
  padding: 0 11px;
  border-radius: 99px;
  border: 1px solid rgba(94, 243, 255, 0.18);
  background: rgba(94, 243, 255, 0.045);
  color: #a9f4ff;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: clamp(18px, 3vh, 30px);
}

.badge-sep {
  width: 1px;
  height: 10px;
  background: rgba(94, 243, 255, 0.2);
}

.hero-logo {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.5vw, 18px);
  margin-bottom: 14px;
}

.hero-mark {
  width: clamp(56px, 7vw, 84px);
  height: clamp(56px, 7vw, 84px);
  color: var(--cyan);
  filter: drop-shadow(0 0 22px rgba(94, 243, 255, 0.22));
  flex: 0 0 auto;
}

.hero-mark svg {
  width: 100%;
  height: 100%;
}

.hero-logo h1 {
  margin: 0;
  font-size: clamp(58px, 8.4vw, 112px);
  line-height: 0.82;
  font-weight: 600;
  letter-spacing: 0.055em;
  background: linear-gradient(105deg, #ffffff 4%, #bff9ff 30%, #72eaff 48%, #b7a5ff 72%, #ff9fe9 96%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 32px rgba(94, 243, 255, 0.13));
}

.hero-kicker {
  margin: 0 0 10px;
  color: var(--gold);
  font-size: clamp(9px, 1vw, 11px);
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.hero-copy {
  margin: 0 0 clamp(22px, 3.5vh, 34px);
  max-width: 480px;
  color: var(--muted);
  font-size: clamp(13px, 1.25vw, 15px);
  line-height: 1.7;
}

.start-form {
  max-width: 520px;
  margin-bottom: 18px;
}

.start-form > label {
  display: block;
  margin-bottom: 7px;
  color: var(--dim);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.name-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 9px;
}

.name-prefix {
  position: absolute;
  margin-left: 16px;
  margin-top: 17px;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 14px;
  opacity: 0.7;
  pointer-events: none;
}

#playerName {
  width: 100%;
  height: 54px;
  padding: 0 15px 0 33px;
  border: 1px solid rgba(132, 166, 255, 0.2);
  border-radius: 15px;
  background: rgba(8, 13, 30, 0.72);
  color: var(--text);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
  backdrop-filter: blur(10px);
}

#playerName::placeholder {
  color: var(--dim);
}

#playerName:focus {
  border-color: rgba(94, 243, 255, 0.5);
  background: rgba(8, 16, 36, 0.82);
  box-shadow: 0 0 0 4px rgba(94, 243, 255, 0.07);
}

#playerName.invalid {
  border-color: rgba(255, 122, 138, 0.65);
  animation: shakeX 0.4s;
}

@keyframes shakeX {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

.start-form-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 10px;
  color: var(--dim);
  font-size: 10px;
}

.new-run {
  margin-top: 10px;
  color: var(--dim);
}

.new-run:hover {
  color: var(--gold);
}

.start-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  color: var(--muted);
  font-size: 10px;
  margin-bottom: 22px;
}

.start-meta b {
  color: var(--text);
  font-weight: 500;
}

.meta-sep {
  width: 1px;
  height: 10px;
  background: rgba(132, 166, 255, 0.16);
}

.start-league {
  max-width: 520px;
  padding: 13px 15px 11px;
  border: 1px solid var(--stroke);
  border-radius: 17px;
  background: rgba(9, 14, 31, 0.58);
  backdrop-filter: blur(12px);
}

.start-league-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 7px;
  color: var(--dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

.start-top3 {
  display: flex;
  flex-direction: column;
}

.start-top-row {
  display: grid;
  grid-template-columns: 20px 25px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
}

.start-top-row .mini-avatar {
  width: 25px;
  height: 25px;
  font-size: 7px;
}

.start-top-row .mini-rank {
  text-align: left;
}

.start-top-empty {
  padding: 10px 0 7px;
  color: var(--dim);
  font-size: 10px;
}

.start-visual {
  position: relative;
  min-height: clamp(360px, 54vh, 570px);
  display: grid;
  place-items: center;
}

.prism-art {
  position: relative;
  width: min(100%, 560px);
  aspect-ratio: 1;
  animation: prismFloat 9s ease-in-out infinite;
  filter: drop-shadow(0 40px 60px rgba(0, 0, 0, 0.4));
}

.prism-art svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

@keyframes prismFloat {
  0%, 100% { transform: translateY(0) rotate(-0.4deg); }
  50% { transform: translateY(-13px) rotate(0.5deg); }
}

.spin-slow {
  transform-origin: 260px 260px;
  animation: spin 46s linear infinite;
}

.spin-reverse {
  transform-origin: 260px 260px;
  animation: spin 64s linear infinite reverse;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.beam-flicker {
  animation: beamFlicker 3.2s ease-in-out infinite;
}

@keyframes beamFlicker {
  0%, 100% { opacity: 0.5; }
  45% { opacity: 0.9; }
  55% { opacity: 0.62; }
}

.orbit {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(94, 243, 255, 0.08);
  pointer-events: none;
}

.orbit-1 {
  width: min(72%, 430px);
  aspect-ratio: 1;
  border-style: dashed;
  animation: spin 70s linear infinite;
}

.orbit-2 {
  width: min(88%, 510px);
  aspect-ratio: 1;
  border-color: rgba(255, 95, 220, 0.055);
  animation: spin 95s linear infinite reverse;
}

.orbit-3 {
  width: min(52%, 320px);
  aspect-ratio: 1;
  border-color: rgba(154, 123, 255, 0.12);
}

.float-card {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 12px;
  border: 1px solid rgba(132, 166, 255, 0.16);
  border-radius: 12px;
  background: rgba(9, 15, 33, 0.76);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(14px);
  animation: cardFloat 7s ease-in-out infinite;
}

.float-card > span:last-child {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.float-card small {
  color: var(--dim);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

.float-card b {
  color: var(--text);
  font-size: 12px;
  font-weight: 500;
}

.float-icon {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border-radius: 8px;
  background: rgba(94, 243, 255, 0.08);
  color: var(--cyan);
  font-size: 15px;
}

.float-icon.amber { background: rgba(255, 207, 112, 0.08); color: var(--gold); }
.float-icon.magenta { background: rgba(255, 95, 220, 0.08); color: var(--magenta); }

.float-a { top: 13%; right: 4%; }
.float-b { bottom: 19%; left: 1%; animation-delay: -2.4s; }
.float-c { bottom: 6%; right: 8%; animation-delay: -4.6s; }

@keyframes cardFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-9px); }
}

.start-footer {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 11px;
  padding: 16px 24px calc(16px + env(safe-area-inset-bottom, 0px));
  border-top: 1px solid rgba(132, 166, 255, 0.07);
  color: var(--dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

/* ----------------------------------- Modals -------------------------------- */

.modal-root {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: 22px;
  overflow-y: auto;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2, 4, 12, 0.74);
  backdrop-filter: blur(13px);
  -webkit-backdrop-filter: blur(13px);
  animation: fadeIn 0.25s ease both;
}

.modal-card {
  position: relative;
  width: min(720px, 100%);
  max-height: min(90vh, 920px);
  overflow-y: auto;
  padding: 26px;
  border: 1px solid rgba(132, 166, 255, 0.18);
  border-radius: 27px;
  background:
    radial-gradient(ellipse 80% 60% at 50% 0%, rgba(94, 243, 255, 0.055), transparent 65%),
    linear-gradient(160deg, rgba(17, 24, 50, 0.97), rgba(7, 11, 26, 0.98));
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  animation: modalIn 0.38s var(--ease) both;
}

.modal-card.narrow {
  width: min(540px, 100%);
}

.modal-card.wide {
  width: min(800px, 100%);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modalIn {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.modal-title-wrap {
  min-width: 0;
}

.modal-eyebrow {
  color: var(--cyan);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.modal-card h2 {
  margin: 0;
  font-size: clamp(23px, 3vw, 31px);
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.15;
}

.modal-sub {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  max-width: 520px;
}

.modal-close {
  flex: 0 0 auto;
}

.modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 22px;
}

.modal-actions.split {
  justify-content: space-between;
}

.modal-actions .btn {
  min-width: 116px;
}

/* --------------------------------- Help modal ------------------------------ */

.help-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 18px 0;
}

.help-card {
  padding: 14px;
  border: 1px solid var(--stroke);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.022);
}

.help-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  margin-bottom: 10px;
  border-radius: 10px;
  background: rgba(94, 243, 255, 0.07);
  color: var(--cyan);
  font-size: 17px;
}

.help-card.amber .help-icon { background: rgba(255, 207, 112, 0.07); color: var(--gold); }
.help-card.magenta .help-icon { background: rgba(255, 95, 220, 0.07); color: var(--magenta); }

.help-card h3 {
  margin: 0 0 4px;
  font-size: 12px;
  font-weight: 600;
}

.help-card p {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.help-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px;
  border: 1px solid var(--stroke);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.018);
}

.help-line {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.help-line b {
  color: var(--text);
  font-weight: 600;
}

.help-num {
  flex: 0 0 auto;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(94, 243, 255, 0.2);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
}

/* ------------------------------- Leaderboard ------------------------------- */

.lb-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.lb-tabs {
  display: inline-flex;
  padding: 3px;
  border: 1px solid var(--stroke);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.025);
}

.lb-tab {
  height: 28px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--dim);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color 0.2s, background 0.2s;
}

.lb-tab.active {
  background: rgba(94, 243, 255, 0.1);
  color: var(--cyan);
}

.lb-tab:hover:not(.active) {
  color: var(--muted);
}

.lb-countdown {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--dim);
  font-size: 9px;
}

.lb-countdown b {
  color: var(--text);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
}

.podium {
  display: grid;
  grid-template-columns: 1fr 1.12fr 1fr;
  align-items: end;
  gap: 8px;
  margin: 6px 0 16px;
  padding: 14px 10px 0;
  border: 1px solid var(--stroke);
  border-radius: 18px;
  background:
    radial-gradient(ellipse 70% 65% at 50% 110%, rgba(94, 243, 255, 0.08), transparent 70%),
    rgba(255, 255, 255, 0.018);
}

.podium-entry {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  min-width: 0;
  text-align: center;
  padding-bottom: 12px;
}

.podium-entry.first {
  padding-bottom: 18px;
}

.podium-medal {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(255, 207, 112, 0.3);
  background: rgba(255, 207, 112, 0.08);
  color: var(--gold);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 600;
  margin-bottom: 3px;
}

.podium-entry.first .podium-medal {
  width: 44px;
  height: 44px;
  font-size: 14px;
  box-shadow: 0 0 26px rgba(255, 207, 112, 0.18);
}

.podium-entry.second .podium-medal { border-color: rgba(207, 216, 234, 0.3); background: rgba(207, 216, 234, 0.07); color: #cfd8ea; }
.podium-entry.third .podium-medal { border-color: rgba(227, 161, 119, 0.3); background: rgba(227, 161, 119, 0.07); color: #e3a177; }

.podium-avatar {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--a, #58f3ff), var(--b, #9a7bff));
  color: #06101a;
  font-size: 10px;
  font-weight: 700;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45);
}

.podium-entry.first .podium-avatar {
  width: 48px;
  height: 48px;
  font-size: 12px;
}

.podium-name {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
}

.podium-entry.first .podium-name { color: var(--text); }

.podium-score {
  color: var(--text);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
}

.podium-time {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 8px;
}

.podium-self {
  display: inline-block;
  padding: 1px 5px;
  border-radius: 99px;
  background: rgba(94, 243, 255, 0.12);
  color: var(--cyan);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.lb-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.lb-row {
  display: grid;
  grid-template-columns: 34px 36px minmax(0, 1fr) 90px 64px;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: 11px;
  transition: background 0.2s, border-color 0.2s;
}

.lb-row:hover {
  background: rgba(255, 255, 255, 0.025);
}

.lb-row.self {
  border-color: rgba(94, 243, 255, 0.2);
  background: rgba(94, 243, 255, 0.055);
}

.lb-rank {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 10px;
  text-align: right;
}

.lb-row:nth-child(1) .lb-rank,
.lb-row:nth-child(2) .lb-rank,
.lb-row:nth-child(3) .lb-rank {
  color: var(--muted);
}

.lb-avatar {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--a, #58f3ff), var(--b, #9a7bff));
  color: #06101a;
  font-size: 8px;
  font-weight: 700;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.lb-name {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}

.lb-name span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-size: 11px;
  font-weight: 500;
}

.lb-row.self .lb-name span:first-child {
  color: var(--text);
}

.self-badge {
  flex: 0 0 auto;
  padding: 2px 6px;
  border-radius: 99px;
  background: rgba(94, 243, 255, 0.12);
  color: var(--cyan);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.lb-score {
  color: var(--text);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  text-align: right;
}

.lb-time {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 9px;
  text-align: right;
}

.lb-empty {
  padding: 34px 16px;
  text-align: center;
