}

/* ------------------------------- Level result ------------------------------ */

.result-stars {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin: 2px 0 14px;
}

.result-star {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  color: rgba(255, 255, 255, 0.1);
  font-size: 30px;
  line-height: 1;
  transition: color 0.3s, transform 0.3s;
}

.result-star.on {
  color: var(--gold);
  text-shadow: 0 0 22px rgba(255, 207, 112, 0.55);
  animation: starPop 0.45s var(--ease) both;
}

.result-star.on:nth-child(2) { animation-delay: 0.1s; }
.result-star.on:nth-child(3) { animation-delay: 0.2s; }

@keyframes starPop {
  0% { transform: scale(0.4) rotate(-18deg); opacity: 0; }
  70% { transform: scale(1.12) rotate(3deg); opacity: 1; }
  100% { transform: scale(1) rotate(0); }
}

.result-score {
  text-align: center;
  margin: 0 0 20px;
}

.result-score small {
