function checkWeekRollover() {
  const info = getWeekInfo()
  if (info.key === state.week.key) return
  const previous = state.week
  state.week = info
  state.league = makeLeague(info.key)
  state.league.refresh().then(() => {
    renderMiniBoard()
    renderStartTop3()
  }).catch(() => {})
  if (state.phase === 'start') {
    state.savedRun = null
